policies.inbound:










        ai-foundry-client


        {{keycloak-issuer-url}}











<set-variable name="userRoles" value="@(String.Join(",", ((Jwt)context.Variables["jwt"])?.Claims.GetValueOrDefault("realm_access", "{}").Replace("{", "").Replace("}", "").Split(',').Where(s => s.Contains("roles")).SelectMany(s => s.Split(':').Skip(1)).Select(s => s.Trim().Replace("[", "").Replace("]", "").Replace("\"", "")).ToArray() ?? new string[0]))" />




    @((string)context.Variables["userId"])


    @((string)context.Variables["userEmail"])


    @((string)context.Variables["userRoles"])




    @{
        return new JObject(
            new JProperty("event", "user_authenticated"),
            new JProperty("userId", (string)context.Variables["userId"]),
            new JProperty("userEmail", (string)context.Variables["userEmail"]),
            new JProperty("userRoles", (string)context.Variables["userRoles"]),
            new JProperty("timestamp", (string)context.Variables["requestTimestamp"]),
            new JProperty("operationId", context.RequestId),
            new JProperty("apiPath", context.Request.Url.Path)
        ).ToString();
    }







<set-variable name="requestBody" value="@(context.Request.Body.As(preserveContent: true))" />


<set-variable name="promptData" value="@{
    try {
        var body = JObject.Parse((string)context.Variables["requestBody"]);
        var messages = body["messages"];
        if (messages != null && messages.HasValues) {
            var userMessages = messages.Where(m => m["role"]?.ToString() == "user").ToList();
            var lastUserMessage = userMessages.LastOrDefault();
            return new JObject(
                new JProperty("lastUserPrompt", lastUserMessage?["content"]?.ToString()?.Substring(0, Math.Min(500, lastUserMessage?["content"]?.ToString()?.Length ?? 0)) ?? ""),
                new JProperty("totalMessages", messages.Count()),
                new JProperty("userMessageCount", userMessages.Count),
                new JProperty("model", body["model"]?.ToString() ?? "unknown"),
                new JProperty("temperature", body["temperature"]?.Value() ?? 1.0),
                new JProperty("maxTokens", body["max_tokens"]?.Value() ?? 0)
            ).ToString();
        }
        return new JObject(new JProperty("format", "non-chat")).ToString();
    } catch {
        return new JObject(new JProperty("parseError", true)).ToString();
    }
}" />


@{
    return new JObject(
        new JProperty("eventType", "ai_prompt_request"),
        new JProperty("userId", (string)context.Variables["userId"]),
        new JProperty("userEmail", (string)context.Variables["userEmail"]),
        new JProperty("userRoles", (string)context.Variables["userRoles"]),
        new JProperty("timestamp", (string)context.Variables["requestTimestamp"]),
        new JProperty("operationId", context.RequestId),
        new JProperty("apiPath", context.Request.Url.Path),
        new JProperty("prompt", JObject.Parse((string)context.Variables["promptData"])),
        new JProperty("clientIp", context.Request.IpAddress),
        new JProperty("subscriptionId", context.Subscription?.Id ?? "unknown"),
        new JProperty("productId", context.Product?.Id ?? "unknown")
    ).ToString();
}

on-error.log-to-eventhub:
@{
            return new JObject(
                new JProperty("eventType", "ai_request_error"),
                new JProperty("userId", context.Variables.ContainsKey("userId") ? (string)context.Variables["userId"] : "unknown"),
                new JProperty("timestamp", DateTime.UtcNow.ToString("o")),
                new JProperty("operationId", context.RequestId),
                new JProperty("error", context.LastError.Message),
                new JProperty("errorReason", context.LastError.Reason),
                new JProperty("statusCode", context.Response?.StatusCode ?? 500)
            ).ToString();
        }

trace.message:
@{
                return new JObject(
                    new JProperty("event", "ai_request_error"),
                    new JProperty("userId", context.Variables.ContainsKey("userId") ? (string)context.Variables["userId"] : "unknown"),
                    new JProperty("operationId", context.RequestId),
                    new JProperty("error", context.LastError.Message)
                ).ToString();
            }
